/// Checks if the obligation is safe from liquidation based on current obligation freshness. If the obligation data is not
/// latest, the result could be delayed. This could be acceptable in some cases, but for liquidation, called should refresh
/// obligation to latest state!
fun is_obligation_safe<MarketType>(
    emode_group: &EModeGroup,
    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,

    obligation: &Obligation<MarketType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): bool {
    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
    let borrow_weight_weighted_debt_value = debts_value_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    let (collateral_weighted_value, _) = collaterals_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    // NOTE: if collaterals_value == borrow_weight_weighted_debt_value, this is still safe, the boundary of safety
    collateral_weighted_value.ge(borrow_weight_weighted_debt_value)
}

// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
fun collaterals_usd_non_liquidation<MarketType>(
    emode_group: &EModeGroup,
    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,

    obligation: &Obligation<MarketType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): (Decimal, Decimal) {
    let mut total_weighted_usd = float::zero();
    let mut total_collateral_usd = float::zero();

/// @title Module for hanlding withdraw base asset request from user
/// @notice User use sCoin to redeem the underlying asset
module protocol::withdraw;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::event::emit;
use sui::coin::Coin;

use x_oracle::x_oracle::XOracle;

use protocol::app::ProtocolApp;
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::ctoken::CToken;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_deposit_reward_type;

public struct WithdrawEvent has copy, drop {
    redeemer: address,

    market: TypeName,
    obligation: ID,

    withdraw_asset: TypeName,
    withdraw_amount: u64,
    ctokens_remaining: u64,

    burn_asset: TypeName,
    burn_amount: u64,
    time: u64,
}

public fun withdraw_as_coin<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    ctoken_to_burn: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = sui::clock::timestamp_ms(clock) / 1000;

    let (coin, ctokens_remaining) = market.handle_withdraw<MarketType, CoinType>(
        obligation_owner_cap.id(),
        ctoken_to_burn,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_deposit_reward_type(),
        obligation_owner_cap.id(),
        ctokens_remaining,
        clock
    );

    // emit Redeem Event
    emit(WithdrawEvent {
        redeemer: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        withdraw_asset: type_name::with_defining_ids<CoinType>(),
        withdraw_amount: coin.value(),
        ctokens_remaining,

        burn_asset: type_name::with_defining_ids<CToken<MarketType, CoinType>>(),
        burn_amount: ctoken_to_burn,

        time: now,
    });

    coin
}

#[allow(lint(self_transfer))]
public fun withdraw<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let coin = withdraw_as_coin<MarketType, CoinType>(
        app,
        market,
        obligation_owner_cap,
        coin_decimals_registry, 
        amount, 
        x_oracle, 
        clock, 
        ctx
    );
    transfer::public_transfer(coin, ctx.sender());
}

